def max_coins(nums):
    a = [1] + nums + [1]               # padded ends
    n = len(a)
    dp = [[0] * n for _ in range(n)]   # dp[i][j]: best for the open interval (i, j)
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):  # k is the LAST balloon burst in (i, j)
                dp[i][j] = max(dp[i][j], dp[i][k] + a[i] * a[k] * a[j] + dp[k][j])
    return dp[0][n - 1]

