def longest_palindrome(s):
    start, length = 0, 0
    for center in range(2 * len(s) - 1):   # n letters + n-1 gaps
        l, r = center // 2, (center + 1) // 2
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        if r - l - 1 > length:
            start, length = l + 1, r - l - 1
    return s[start:start + length]

